var output = new BoundedFrameOutputStream(blocked, 1, 64);
try {
    output.write("one\n".getBytes(StandardCharsets.UTF_8));
    IOException failure = assertThrows(IOException.class,
            () -> output.write("two\n".getBytes(StandardCharsets.UTF_8)));
    assertTrue(failure.getMessage().contains("protocol.slow_consumer"));
    assertTrue(failure.getMessage().contains("bufferBytes=64"));
    assertTrue(failure.getMessage().contains("bufferFrames=1"));
} finally {
    release.countDown();
    try { output.close(); } catch (IOException ignored) { }

